                grant_id=grant_id,
                authorization_event_id=grant["event_id"],
                type="consumed",
                occurred_at=consumed_at,
            )
            uses.append(
                {
                    "grant_id": grant_id,
                    "use_id": use_id,
                    "consumed_at": consumed_at,
                }
            )
        return {"status": "ok", "uses": uses}

    try:
